Q: How to get vue&#39;s v-else-if functionality in angular? A: <p>You can take advantage of the modern control flow syntax:</p>
<pre class="lang-html prettyprint-override"><code>&lt;!-- my-component.html --&gt;
@if (condition1) {
  &lt;div&gt;Condition1 is true&lt;/div&gt;
} @else if (condition2) {
  &lt;div&gt;Condition2 is true&lt;/div&gt;
} @else if (condition3) {
  &lt;div&gt;Condition3 is true&lt;/div&gt;
} @else {
  &lt;div&gt;All of the above conditions are false&lt;/div&gt;
}
</code></pre>
<p>See this <a href="https://stackblitz.com/edit/f7suzhvq?file=src%2Fmain.ts" rel="nofollow noreferrer">https://stackblitz.com/edit/f7suzhvq?file=src%2Fmain.ts</a></p>

Q: What is the implementation of `strtol`? A: <p>my implementation</p>
<pre class="lang-c prettyprint-override"><code>static int  ft_isspace(int c)
{
    return (c == ' ' || (c &gt;= 9 &amp;&amp; c &lt;= 13));
}

static unsigned long    my_stoul(const char *s, char **endptr)
{
    unsigned long       result;
    int                 i;

    result = 0;
    i = 0;
    while (s[i] &gt;= '0' &amp;&amp; s[i] &lt;= '9')
    {
        result = result * 10 + (s[i] - '0');
        i++;
    }
    if (endptr)
        *endptr = (char *)&amp;s[i];
    return (result);
}

long    my_strtol(const char *s, char **endptr)
{
    char            *se;
    int             sign;
    unsigned long   x;

    if (endptr == NULL)
        endptr = &amp;se;
    *endptr = (char *)s;
    while (ft_isspace(*s))
        s++;
    sign = 1;
    if (*s == '-' || *s == '+')
    {
        if (*s == '-')
            sign = -1;
        s++;
    }
    x = my_stoul(s, endptr);
    if (s == *endptr)
        *endptr = (char *)s;
    if (sign == 1 &amp;&amp; x &gt; (unsigned long)LONG_MAX)
        return (LONG_MAX);
    else if (sign == -1 &amp;&amp; x &gt; (unsigned long)LONG_MAX)
        return (LONG_MIN);
    else
        return ((long)x * sign);
}
</code></pre>
